def update_pheromone(tau, tours, lens, rho):
    new = (1 - rho) * tau                              # випаровування (нова матриця, tau не чіпаємо)
    for g, L in zip(tours, lens):
        t = np.concatenate(([0], g, [0]))              # з вокзалу і назад на вокзал
        new[t[:-1], t[1:]] += 1.0 / L                  # напрямлені ребра i → j
    return new
